import json, math, time
from pathlib import Path
from collections import defaultdict, Counter
from dataclasses import replace
from fractions import Fraction
from ortools.sat.python import cp_model
from games.tw.attila.compact import Builder, common_unit
from games.tw.attila.partition import partition
from games.tw.attila.native_parts import extract, objective_terms, objective_value, feasible
from games.tw.attila.algebra import add, multiply, rational
from games.tw.competition import integer_row
from twoptimizer.attila_session import AttilaSession
from twoptimizer.requests import default_config, make_jobs
START = time.perf_counter()
config = make_jobs(replace(default_config('attila'), provinces=('all',), joint=True, workers=4))[0][0]
state = AttilaSession()
prepared = state.prepare(config)
reference = prepared.snapshot.model
builder = Builder(reference.cp_sat_plan, reference)
native, native_unit = builder.build()
decomposition = partition(builder)
coefficients, native_offset = objective_terms(native)
part_of_native = {v: p for p, part in enumerate(decomposition.parts) for v in part.indices}
part_of_reference, fixed_reference = {}, {}
for i in range(len(reference.names)):
    if i in builder.products:
        continue
    ni = builder.variables[i].index
    if ni in decomposition.fixed:
        fixed_reference[i] = decomposition.fixed[ni]
    else:
        part_of_reference[i] = part_of_native[ni]
for i, leaves in builder.products.items():
    if any(fixed_reference.get(v) == 0 for v in leaves):
        fixed_reference[i] = 0
        continue
    groups = {part_of_reference[v] for v in leaves if v not in fixed_reference}
    if len(groups) > 1:
        raise RuntimeError(('cross-product', i, groups))
    if groups:
        part_of_reference[i] = groups.pop()
    else:
        fixed_reference[i] = 1
rows_by_part = defaultdict(list)
constant_rows = []
reference_rows = list(reference.row_entries())
for row, (indices, amounts) in enumerate(reference_rows):
    if row in decomposition.relaxed_reference_rows:
        continue
    owners = {part_of_reference[int(i)] for i,c in zip(indices,amounts) if c and int(i) not in fixed_reference}
    if len(owners)>1:
        raise RuntimeError(('retained_cross_row', row, owners))
    if owners:
        rows_by_part[owners.pop()].append(row)
    else:
        constant_rows.append(row)
province_parts = defaultdict(set)
for name, b in builder.plan.economy.by_id.items():
    i = builder.indices[builder.plan.aliases[name]]
    if i in part_of_reference:
        province_parts[builder.plan.economy.owner[b.region.name]].add(part_of_reference[i])
metadata = dict(preparation_seconds=time.perf_counter()-START, reference_variables=len(reference.names), reference_rows=len(reference_rows), native_variables=len(native.proto.variables), native_rows=len(native.proto.constraints), parts=len(decomposition.parts), native_unit=str(native_unit), constant_native=decomposition.constant, fixed_reference=len(fixed_reference), constant_rows=len(constant_rows), relaxed_reference_rows=len(decomposition.relaxed_reference_rows), province_parts={k:sorted(v) for k,v in province_parts.items()})
print(json.dumps(metadata,indent=2),flush=True)
Path('/tmp/attila-local-preparation.json').write_text(json.dumps(metadata,indent=2))
print('PREPARED',flush=True)
